"use client"

import { ChevronDownIcon } from "lucide-react"
import { cn } from "cn"

import { LinkButton } from "@/components/ui/button"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import { SemanticContent } from "@/components/ui/semantic-content"

type Heading = { id: string; label: string; level?: 2 | 3 }

/**
 * Table of contents (after diceui scroll-spy). tracking.css: the active entry
 * comes from `activeId` (or the URL fragment via :target styling on the page),
 * no scroll listener. Collapses behind a Disclosure below md.
 */
export default function TableOfContents({
  label = "On this page",
  headings = [
    { id: "overview", label: "Overview" },
    { id: "install", label: "Install" },
    { id: "usage", label: "Usage", level: 3 },
    { id: "api", label: "API reference" },
  ],
  activeId,
}: {
  label?: string
  headings?: Heading[]
  activeId?: string
}) {
  const list = (
    <ol className="flex flex-col gap-0.5 border-l border-border">
      {headings.map((h) => (
        <li key={h.id}>
          <LinkButton
            href={`#${h.id}`}
            variant="ghost"
            size="sm"
            aria-current={h.id === activeId ? "location" : undefined}
            className={cn(
              "-ml-px h-auto w-full justify-start rounded-none border-l border-transparent py-1 font-normal whitespace-normal text-muted-foreground aria-[current]:border-primary aria-[current]:text-foreground",
              h.level === 3 && "pl-6"
            )}
          >
            {h.label}
          </LinkButton>
        </li>
      ))}
    </ol>
  )
  return (
    <nav aria-label={label} data-slot="table-of-contents" className="text-sm">
      <div className="hidden md:block">
        <SemanticContent as="p" className="mb-2 font-medium">{label}</SemanticContent>
        {list}
      </div>
      <Collapsible className="md:hidden">
        <CollapsibleTrigger className="group flex w-full items-center justify-between py-2 font-medium">
          {label}
          <ChevronDownIcon className="size-4 transition-transform group-aria-expanded:rotate-180" />
        </CollapsibleTrigger>
        <CollapsibleContent>{list}</CollapsibleContent>
      </Collapsible>
    </nav>
  )
}
